contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(
        address vader,
        address usdv,
        address vault,
        address proposed,
        string memory typeStr,
        uint proposalID
    ) public {
        c.init(vader, usdv, vault); if (__ESBMC_reverted()) return;
        c.newAddressProposal(proposed, typeStr); if (__ESBMC_reverted()) return;

        uint countBefore = c.proposalCount(); if (__ESBMC_reverted()) return;
        require(countBefore >= 1, "need a proposal");
        require(proposalID >= 1 && proposalID <= countBefore, "proposalID out of range");

        bool finalisingBefore = c.mapPID_finalising(proposalID); if (__ESBMC_reverted()) return;

        bool reverted;
        uint voteWeight;
        uint256 w = c.voteProposal(proposalID); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
            voteWeight = w;
        }

        bool finalisingAfter = c.mapPID_finalising(proposalID); if (__ESBMC_reverted()) return;

        assert(
            reverted ||
            finalisingBefore ||
            !finalisingAfter ||
            (c.mapPID_finalising(proposalID) == true)
        );
    }
}

